export function translationsForModule(id: string): Partial<Record<UserLanguage, Record<string, string>>> {
  const specific = local[id] ?? {};
  const extra = extended[id] ?? {};
  const more = extendedMore[id] ?? {};
  const final = extendedFinal[id] ?? {};
  return Object.fromEntries((Object.keys(shared) as UserLanguage[]).map((language) => [language, { ...shared[language], ...(sharedTerms[language] ?? {}), ...(specific[language] ?? {}), ...(extra[language] ?? {}), ...(more[language] ?? {}), ...(final[language] ?? {}) }])) as Partial<Record<UserLanguage, Record<string, string>>>;
}
